from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import itertools

# Vertices: 20
# Edges: 46
# Max label: 46

edges = []
for g in range(5):
    for i in range(4):
        for j in range(i+1, 4):
            edges.append((g*4 + i, g*4 + j))

for g in range(4):
    for i in range(4):
        edges.append((g*4 + i, (g+1)*4 + i))

V = 20
E = 46

def v_var(v, val):
    return v * 47 + val + 1

def e_var(e, val):
    return V * 47 + e * 46 + val

solver = Glucose4()

# Each vertex has exactly one value
for v in range(V):
    vars = [v_var(v, val) for val in range(47)]
    solver.add_clause(vars)
    for i in range(47):
        for j in range(i+1, 47):
            solver.add_clause([-vars[i], -vars[j]])

# Each edge has exactly one value
for e in range(E):
    vars = [e_var(e, val) for val in range(1, 47)]
    solver.add_clause(vars)
    for i in range(46):
        for j in range(i+1, 46):
            solver.add_clause([-vars[i], -vars[j]])

# Distinct vertex values
for val in range(47):
    vars = [v_var(v, val) for v in range(V)]
    for i in range(V):
        for j in range(i+1, V):
            solver.add_clause([-vars[i], -vars[j]])

# Distinct edge values
for val in range(1, 47):
    vars = [e_var(e, val) for e in range(E)]
    for i in range(E):
        for j in range(i+1, E):
            solver.add_clause([-vars[i], -vars[j]])

# Edge value definition
for e_idx, (u, v) in enumerate(edges):
    for val1 in range(47):
        for val2 in range(47):
            if val1 != val2:
                diff = abs(val1 - val2)
                # If u is val1 and v is val2, then edge is diff
                solver.add_clause([-v_var(u, val1), -v_var(v, val2), e_var(e_idx, diff)])

# Symmetry breaking
# 1. V[0] < V[1] < V[2] < V[3]
for i in range(3):
    for val1 in range(47):
        for val2 in range(val1 + 1):
            solver.add_clause([-v_var(i, val1), -v_var(i+1, val2)])

# 2. Reverse graph symmetry: The graph is symmetric if we reverse the cliques (clique 0 <-> clique 4, etc.)
# So we can enforce that the sum of labels in clique 0 is less than clique 4, or simply V[0] < V[16]
for val1 in range(47):
    for val2 in range(val1 + 1):
        solver.add_clause([-v_var(0, val1), -v_var(16, val2)])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    labels = [-1] * V
    for v in range(V):
        for val in range(47):
            if v_var(v, val) in model:
                labels[v] = val
    print(labels)
else:
    print("UNSAT")

